import React, { useEffect, useState } from "react";
import { API_BASE_URL, authFetchJson } from "../../../services/api";

function Drinkharddrink() {
  const [data, setdata] = useState([]);
  const [error, seterror] = useState("");
  const [category, setCategory] = useState("beer"); // default
  const [selectedItem, setSelectedItem] = useState("");

  const BASEAPI = "https://afmc.globalsparkteksolutions.com/AFMCIMAGES/";

  // 🔥 Dynamic API call
  const fetchdata = async (type) => {
    try {
      const result = await authFetchJson(`${API_BASE_URL}/Drinkhard${type}`);
      setdata(result?.data || []);
    } catch (error) {
      console.error("Failed to fetch hard drinks:", error);
      seterror(error.message);
    }
  };

  // 🔥 Run API when category changes
  useEffect(() => {
    fetchdata(category);
  }, [category]);

  if (error) {
    return <div>{error}</div>;
  }

  const visibleItems = selectedItem ? data.filter((it) => it.item_name === selectedItem) : data;

  return (
    <div style={{ padding: "20px", background: "#f5f5f5" }}>
    
      {/* ✅ Category Tabs */}
      <div style={styles.categoryTabs}>
        {categories.map((cat) => (
          <span
            key={cat.value}
            onClick={() => setCategory(cat.value)}
            style={
              category === cat.value
                ? styles.activeCategory
                : styles.category
            }
          >
            {cat.label}
          </span>
        ))}
      </div>

      {/* Filter */}
      <div style={styles.filterBox}>
        <div>
          <label>Item Name</label>
          <select
            style={styles.select}
            value={selectedItem}
            onChange={(e) => setSelectedItem(e.target.value)}
          >
            <option value="">All Items</option>
            {data.map((item, index) => (
              <option key={index}>{item.item_name}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Items Grid */}
      <div style={styles.grid}>
        {visibleItems.map((item, index) => (
          <div key={index} style={styles.card}>
            
            {/* Image */}
            <img
              src={`${BASEAPI}${item.image}`}
              alt={item.item_name}
              style={styles.image}
            />

            {/* Name */}
            <div>
              <div style={styles.itemName}>{item.item_name}</div>

              {item.stock_status && (
                <div style={styles.outOfStock}>
                  {item.stock_status}
                </div>
              )}
            </div>

          </div>
        ))}
      </div>
    </div>
  );
}

export default Drinkharddrink;


// ✅ Category Mapping (IMPORTANT)
const categories = [
  { label: "Beer", value: "beer" },
  { label: "Brandy", value: "brandy" },
  { label: "Breezer", value: "breezer" }, // 🔥 THIS CALLS Drinkhardbreezer
  { label: "Vodka", value: "vodka" },
  { label: "Gin", value: "gin" },
  { label: "Rum", value: "rum" },
  { label: "Whisky", value: "whisky" },
  { label: "Wine", value: "wine" },
  { label: "Liquor", value: "liquor" },
  { label: "Tequila", value: "tequila" },
  { label: "Cocktail", value: "cocktail" },
];

const styles = {
  tabContainer: {
    display: "flex",
    gap: "20px",
    marginBottom: "15px",
  },
  tab: {
    padding: "10px 20px",
    borderRadius: "8px",
    background: "#e0e0e0",
    cursor: "pointer",
  },
  activeTab: {
    borderBottom: "3px solid green",
    background: "#fff",
  },
  categoryTabs: {
    display: "flex",
    gap: "15px",
    marginBottom: "20px",
    flexWrap: "wrap",
  },
  category: {
    cursor: "pointer",
  },
  activeCategory: {
    borderBottom: "2px solid green",
    paddingBottom: "5px",
    cursor: "pointer",
  },
  filterBox: {
    display: "flex",
    gap: "40px",
    marginBottom: "20px",
    background: "#fff",
    padding: "15px",
    borderRadius: "10px",
  },
  select: {
    display: "block",
    padding: "8px",
    marginTop: "5px",
    minWidth: "200px",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
    gap: "20px",
  },
  card: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    background: "#fff",
    padding: "12px",
    borderRadius: "10px",
    boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
  },
  image: {
    width: "40px",
    height: "40px",
    borderRadius: "6px",
    objectFit: "cover",
  },
  itemName: {
    fontSize: "14px",
    fontWeight: "500",
  },
  outOfStock: {
    color: "red",
    fontSize: "12px",
    marginTop: "4px",
  },
};
