import React, { useEffect, useState } from "react";
import { API_BASE_URL, authFetchJson } from "../../../services/api";

function EnduserMocktail() {
  const [data, setdata] = useState([]);
  const [error, seterror] = useState("");
  const [selectedItem, setSelectedItem] = useState("");

  const BASEAPI = "https://afmc.globalsparkteksolutions.com/AFMCIMAGES/";

  useEffect(() => {
    fetchdata();
  }, []);

  const fetchdata = async () => {
    try {
      const result = await authFetchJson(`${API_BASE_URL}/fetchmocktail`);
      setdata(result?.data || []);
    } catch (error) {
      console.error("Failed to fetch mocktails:", error);
      seterror(error.message);
    }
  };

  if (error) {
    return <div>{error}</div>;
  }

  const visibleItems = selectedItem ? data.filter((it) => it.item_name === selectedItem) : data;

  return (
    <div style={{ padding: "20px", background: "#f5f5f5" }}>

      {/* Top Tabs */}
      <div style={styles.tabContainer}>
        <div style={{ ...styles.tab, ...styles.activeTab }}>Drinks</div>
        <div style={styles.tab}>Snacks</div>
      </div>

      {/* Sub Tabs */}
      <div style={styles.tabContainer}>
        <div style={{ ...styles.tab, ...styles.activeTab }}>Soft Drinks</div>
        <div style={styles.tab}>Hard Drinks</div>
      </div>

      {/* Category Tabs */}
      <div style={styles.categoryTabs}>
        <span>Others</span>
        <span style={styles.activeCategory}>Mocktail</span>
      </div>

      {/* Filter */}
      <div style={styles.filterBox}>
        <div>
          <label>Item Name</label>
          <select style={styles.select} value={selectedItem} onChange={(e) => setSelectedItem(e.target.value)}>
            <option value="">All Items</option>
            {data.map((item, index) => (
              <option key={index}>{item.item_name}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Items Grid */}
      <div style={styles.grid}>
        {visibleItems.map((item, index) => (
          <div key={index} style={styles.card}>

            {/* Image */}
            <img
              src={`${BASEAPI}${item.image}`}
              alt={item.item_name}
              style={styles.image}
            />

            {/* Name */}
            <div style={styles.itemName}>
              {item.item_name}
            </div>

          </div>
        ))}
      </div>
    </div>
  );
}

export default EnduserMocktail;

const styles = {
  tabContainer: {
    display: "flex",
    gap: "20px",
    marginBottom: "15px",
  },
  tab: {
    padding: "10px 20px",
    borderRadius: "8px",
    background: "#e0e0e0",
    cursor: "pointer",
  },
  activeTab: {
    borderBottom: "3px solid green",
    background: "#fff",
  },
  categoryTabs: {
    display: "flex",
    gap: "20px",
    marginBottom: "20px",
  },
  activeCategory: {
    borderBottom: "2px solid green",
    paddingBottom: "5px",
  },
  filterBox: {
    display: "flex",
    gap: "40px",
    marginBottom: "20px",
    background: "#fff",
    padding: "15px",
    borderRadius: "10px",
  },
  select: {
    display: "block",
    padding: "8px",
    marginTop: "5px",
    minWidth: "200px",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
    gap: "20px",
  },
  card: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    background: "#fff",
    padding: "12px",
    borderRadius: "10px",
    boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
  },
  image: {
    width: "40px",
    height: "40px",
    borderRadius: "6px",
    objectFit: "cover",
  },
  itemName: {
    fontSize: "14px",
    fontWeight: "500",
  },
};
